/****************************************************************************
 * Name: draw_oeye_base
 *
 * Description:
 *   Draw the base oeye: white background, blue iris (r56 with
 *   white border visible), black pupil, two white highlights.
 *   Eyelids are layered on top by the caller.
 *
 ****************************************************************************/

static void draw_oeye_base(void)
{
  /* 1) White background — full screen */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);

  /* 2) Blue iris — r56, leaves ~24px white border all around */

  lcd_fill_circle(80, 80, OEYE_IRIS_R, OEYE_IRIS);

  /* 3) Black pupil */

  lcd_fill_circle(80, 80, OEYE_PUPIL_R, OEYE_PUPIL);

  /* 4) Two white highlights for water-shine effect */

  lcd_fill_circle(OEYE_HL1_X, OEYE_HL1_Y, OEYE_HL1_R, OEYE_HL);
  lcd_fill_circle(OEYE_HL2_X, OEYE_HL2_Y, OEYE_HL2_R, OEYE_HL);
}

/****************************************************************************
 * Name: eye_o_neutral
 *
 * Description:
 *   Neutral / fully open: base eye + thin black eyelid outline.
 *   Upper lid covers top strip, lower lid covers bottom strip,
 *   leaving the blue iris with clear black edge against white bg.
 *
 ****************************************************************************/

static void eye_o_neutral(void)
{
  draw_oeye_base();

  /* Upper eyelid: thin black strip at top */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_NEUTRAL_TOP, OEYE_LID);

  /* Lower eyelid: thin black strip at bottom */

  lcd_fill_rect(0, OEYE_NEUTRAL_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
                OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_half
 *
 * Description:
 *   Half-closed: upper eyelid pushes down covering top half of
 *   blue iris, lower eyelid pushes up covering bottom half.
 *   A band of blue remains visible in the middle.
 *
 ****************************************************************************/

static void eye_o_half(void)
{
  draw_oeye_base();

  /* Upper eyelid: covers top portion of iris */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, OEYE_HALF_TOP, OEYE_LID);

  /* Lower eyelid: covers bottom portion of iris */

  lcd_fill_rect(0, OEYE_HALF_BOT, LCD_WIDTH - 1, LCD_HEIGHT - 1,
                OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_blink
 *
